uniform float speed : 0.0 .. 4.0 = 1.0;
uniform float width : 0.02 .. 0.3 = 0.08;
uniform vec3 color : color = 1.0, 0.2, 0.1;
uniform float tail : 0.0 .. 1.0 = 0.3;

state fixed ph;

void update() {
  ph = fract(ph + fixed(dt * speed * 0.5));
}

vec3 shade(Led led) {
  fixed a = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  fixed d = abs(a - ph);
  if (d > fixed(0.5)) d = fixed(1.0) - d;
  fixed edge = fixed(width * 0.5);
  fixed t = clamp((edge - d) * fixed(1.0 / width), fixed(0.0), fixed(1.0));
  t = t * t;
  fixed falloff = clamp(led.dist * fixed(1.0 / tail), fixed(0.0), fixed(1.0));
  return color * float(t * falloff);
}

