vec3 shade(Led led) {
  fixed a = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  fixed d = abs(a - ph);
  if (d > fixed(0.5)) {
    d = fixed(1.0) - d;
  }
  fixed edge = fixed(width * 0.5);
  fixed t = clamp((edge - d) * fixed(1.0 / width), fixed(0.0), fixed(1.0));
  t = t * t;
  fixed falloff = clamp(led.dist * fixed(1.0 / tail), fixed(0.0), fixed(1.0));
  return color * float(t * falloff);
}
